from typing import Optional


def fib(n: int, memo: Optional[dict] = None) -> int:
    """Return the n-th Fibonacci number."""
    memo = memo if memo is not None else {}
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]


