use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct Cache<'a, T: Default + 'a> {
    map: HashMap<&'a str, Vec<T>>,
}

impl<'a, T: Default> Cache<'a, T> {
    pub fn get_or_default(&mut self, k: &'a str) -> &mut Vec<T> {
        self.map.entry(k).or_insert_with(|| vec![T::default(); 4])
    }
}
